"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6700],{66484:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates the `Path` instance through `PathfindingService:CreatePath`.","params":[{"name":"options","desc":"","lua_type":"NavmeshOptions?"}],"returns":[{"desc":"","lua_type":"Navmesh"}],"function_type":"static","errors":[{"lua_type":"\\"unknown option\\"","desc":"A key that is not in `NavmeshOptions`."}],"source":{"line":119,"path":"lib/Pathfinders/Navmesh.luau"}},{"name":"Simplify","desc":"Removes interior Walk steps that lie on the straight line between the last kept step and the\\nnext one, so a mover walks one long segment instead of many short collinear ones. Pure.\\n\\nAlways kept: the first and last step, every Jump or Custom step, every step with a Label, and\\nthe step immediately before a Jump (the jump origin matters). A path of two or fewer steps\\ncomes back as a copy.","params":[{"name":"path","desc":"","lua_type":"Path"}],"returns":[{"desc":"A new path; the input is not modified.","lua_type":"Path"}],"function_type":"static","source":{"line":179,"path":"lib/Pathfinders/Navmesh.luau"}},{"name":"CollapseLabels","desc":"Merges each run of consecutive steps that share a `Label` into the first of them, keeping\\nits position. A `PathfindingModifier` labels every waypoint inside its volume, and waypoints\\nsit a couple of studs apart, so a doorway would otherwise be two or three \\"Door\\" steps and a\\nhandler would run at each. A run is broken by an unlabelled step or a different label. Pure.","params":[{"name":"path","desc":"","lua_type":"Path"}],"returns":[{"desc":"A new path; the input is not modified.","lua_type":"Path"}],"function_type":"static","source":{"line":216,"path":"lib/Pathfinders/Navmesh.luau"}},{"name":"FromWaypoints","desc":"Converts `Path:GetWaypoints()` output to Steps: `Action` is the waypoint action\'s name and an\\nempty `Label` becomes `nil`. Pure; any table shaped like a waypoint works.","params":[{"name":"waypoints","desc":"","lua_type":"{ PathWaypoint }"}],"returns":[{"desc":"","lua_type":"Path"}],"function_type":"static","source":{"line":240,"path":"lib/Pathfinders/Navmesh.luau"}},{"name":"FindPath","desc":"","params":[{"name":"self","desc":"","lua_type":"Navmesh"},{"name":"from","desc":"","lua_type":"Vector3"},{"name":"to","desc":"","lua_type":"Vector3"},{"name":"agent","desc":"Unused; part of the [Types.Pathfinder] contract.","lua_type":"Agent"}],"returns":[{"desc":"The steps, simplified when `Simplify` is on.","lua_type":"Path?"},{"desc":"On failure: the `ComputeAsync` error text, the `PathStatus` name (`NoPath`, `ClosestNoPath`, ...) or `destroyed`.","lua_type":"string?"}],"function_type":"static","yields":true,"source":{"line":266,"path":"lib/Pathfinders/Navmesh.luau"}},{"name":"Close","desc":"The navmesh is Roblox\'s, so a link cannot be closed for one agent; instead, for `seconds`,\\nany path this pathfinder computes that crosses a step with the same label within a few\\nstuds (or the same `Instance`) is reported as no path, `closed <label> at <position>`. The\\n[Navigator] calls this when a step handler returns `false`.","params":[{"name":"self","desc":"","lua_type":"Navmesh"},{"name":"step","desc":"The step a handler refused.","lua_type":"Step"},{"name":"seconds","desc":"How long to refuse paths through it.","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":348,"path":"lib/Pathfinders/Navmesh.luau"}},{"name":"Destroy","desc":"Destroys the `Path` instance and the `Blocked` signal. `FindPath` after this returns\\n`nil, \\"destroyed\\"`.","params":[{"name":"self","desc":"","lua_type":"Navmesh"}],"returns":[],"function_type":"static","source":{"line":363,"path":"lib/Pathfinders/Navmesh.luau"}}],"properties":[],"types":[{"name":"NavmeshOptions","desc":"","fields":[{"name":"AgentRadius","lua_type":"number?","desc":"Passed to `CreatePath`. Default `2`."},{"name":"AgentHeight","lua_type":"number?","desc":"Passed to `CreatePath`. Default `5`."},{"name":"AgentCanJump","lua_type":"boolean?","desc":"Passed to `CreatePath`. Default `false`."},{"name":"AgentCanClimb","lua_type":"boolean?","desc":"Passed to `CreatePath`. Default `false`."},{"name":"WaypointSpacing","lua_type":"number?","desc":"Passed to `CreatePath`. Default `2`."},{"name":"Costs","lua_type":"{ [string]: number }?","desc":"Material and modifier costs passed to `CreatePath`. Default `{}`."},{"name":"Simplify","lua_type":"boolean?","desc":"Run [Navmesh.Simplify] over every path. Default `true`."},{"name":"CollapseLabels","lua_type":"boolean?","desc":"Run [Navmesh.CollapseLabels] over every path, so a `PathfindingModifier` volume that labels several waypoints in a row yields one labelled step, like a link. Default `true`."}],"source":{"line":51,"path":"lib/Pathfinders/Navmesh.luau"}}],"name":"Navmesh","desc":"A [Types.Pathfinder] over Roblox\'s `PathfindingService`. One `Path` instance per navmesh, created\\nin `new` with the agent parameters and reused for every `FindPath`, so make one per agent rather\\nthan one per plan. Never share one between agents: `ComputeAsync` yields, so a second agent\'s\\nplan would overwrite the waypoints the first is about to read.\\n\\n`Name` is `\\"Navmesh\\"`, which [Ladder] uses in its reasons. `Blocked` fires whenever the\\n`Path` instance reports its last computed path blocked, so a [Navigator] re-plans when a door\\ncloses or a part moves into the way instead of waiting for the mover\'s stuck check.","source":{"line":110,"path":"lib/Pathfinders/Navmesh.luau"}}')}}]);